function zipMsgHtml(inArea,notInArea){if(notInArea)return `<div style="background:#FFE5E5!important;border:1px solid #FF9999!important;border-radius:8px!important;padding:12px!important;font-size:14px!important;color:#C53030!important;"><strong>Outside our service area.</strong> We currently serve Denver &amp; the surrounding metro.<div style="margin-top:8px!important;">Think that's wrong, or want a quote anyway? <a href="tel:${PHONE_TEL}" style="color:#C53030!important;font-weight:700!important;text-decoration:underline!important;">Call us at ${PHONE_DISPLAY}</a></div></div>`;if(inArea)return `<div style="background:#D6E8F7!important;border:1px solid ${BLUE_LIGHT}!important;border-radius:8px!important;padding:12px!important;font-size:14px!important;color:${BLUE_DK}!important;"><strong>&#10003; Great news!</strong> We service your area.</div>`;return '';}
function zipErrorHtml(){return `<div style="background:#FFF6E0!important;border:1px solid #F0C060!important;border-radius:8px!important;padding:12px!important;font-size:14px!important;color:#8A5A00!important;"><strong>Couldn't check right now.</strong> Please try again — or <a href="tel:${PHONE_TEL}" style="color:#8A5A00!important;font-weight:700!important;text-decoration:underline!important;">call us at ${PHONE_DISPLAY}</a>.</div>`;}
function bZipVerify(){const zip=customer.zip||'';const isValid=/^\d{5}$/.test(zip);const PIN=`<svg viewBox="0 0 24 24" width="28" height="28" fill="${BLUE}"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 1 1 0-5 2.5 2.5 0 0 1 0 5z"/></svg>`;const CHEV=`<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>`;return `<h1 style="${S.h1};text-align:center!important;font-size:44px!important;line-height:1.15!important;font-weight:800!important;margin-bottom:6px!important;">Do we service your area?</h1><p style="${S.sub};text-align:center!important;font-size:18px!important;">Enter your zip code to see.</p><div style="display:flex!important;align-items:stretch!important;max-width:380px!important;margin:0 auto 4px auto!important;background:#fff!important;border:2px solid ${BLUE}!important;border-radius:14px!important;overflow:hidden!important;box-shadow:0 2px 8px rgba(0,71,171,0.08)!important;"><span style="display:flex!important;align-items:center!important;padding:0 6px 0 16px!important;flex-shrink:0!important;">${PIN}</span><input type="text" id="verify-zip" style="flex:1!important;min-width:0!important;border:none!important;outline:none!important;background:transparent!important;padding:18px 12px!important;font-size:20px!important;color:${INK}!important;" placeholder="ZIP Code" maxlength="5" inputmode="numeric" value="${zip}" autocomplete="postal-code" autofocus><button id="btn-verify-zip" style="background:${BLUE}!important;border:none!important;width:66px!important;flex-shrink:0!important;display:flex!important;align-items:center!important;justify-content:center!important;cursor:${isValid?'pointer':'not-allowed'}!important;opacity:1!important;" ${!isValid?'disabled':''}>${CHEV}</button></div><div id="zip-msg" style="min-height:30px!important;max-width:380px!important;margin:10px auto 0 auto!important;"></div>`;}
function bFrameTV(){const frameOn=(selections['__frame_type']||[]).includes('frame');const regOn=(selections['__frame_type']||[]).includes('regular');const any=frameOn||regOn;return `<h1 style="${S.h1}">What kind of TV do you have?</h1><p style="${S.sub}">Select each TV type you're mounting. Smart frame TVs like Samsung Frame and LG Gallery come with their own bracket.</p><div class="dom-tv-type" data-type="frame" style="${S.card(frameOn)}"><span>Samsung FrameTV or LG Gallery</span><span style="color:${frameOn?BLUE:'#A7B3BE'}!important;font-size:18px!important;">${frameOn?'✓':'☐'}</span></div><div class="dom-tv-type" data-type="regular" style="${S.card(regOn)}"><span>Traditional TV</span><span style="color:${regOn?BLUE:'#A7B3BE'}!important;font-size:18px!important;">${regOn?'✓':'☐'}</span></div><div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${any?S.btnPri:S.btnDis}" ${!any?'disabled':''}>Continue →</button></div>`;}
function bSize(){const sec=getSec('size');const opts=sec.options.map(o=>{const q=getQty(sec.id,o.id);return `<div style="${S.qRow(q>0)}"><span style="flex:1!important;">${o.label}</span><div style="display:flex!important;align-items:center!important;gap:8px!important;flex-shrink:0!important;"><button class="dom-dec" data-s="${sec.id}" data-o="${o.id}" style="${S.qBtn}">−</button><span style="${S.qNum}">${q}</span><button class="dom-inc" data-s="${sec.id}" data-o="${o.id}" style="${S.qBtn}">+</button></div></div>`;}).join('');const ok=totalTVs()>0;return `<h1 style="${S.h1}">${sec.title}</h1><p style="${S.sub}">${sec.subtitle}</p>${opts}<div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${ok?S.btnPri:S.btnDis}" ${!ok?'disabled':''}>Continue →</button></div>`;}
// Bracket comparison popup: educational modal from the bracket step, adapted
// from Handy Andy's version (github andrewtrading04-star/handy-andy-booking,
// public/widget.js) to Dom's own blue palette and label patterns. Each panel
// has its own "Add to my order" button so a customer can decide and act
// without leaving the popup.
function bracketHelpPanel(numLabel,numBg,title,tagBg,tagColor,tagText,barBg,diagramBg,diagramSvg,desc,pros,cons,optId,sectionId,btnLabel){
  const prosHtml=pros.map(p=>`<li>${p}</li>`).join('');
  const consHtml=cons.map(c=>`<li>${c}</li>`).join('');
  const addBtn=optId?`<button class="dom-bracket-add" data-s="${sectionId}" data-o="${optId}" style="margin-top:12px!important;width:100%!important;background:${BLUE}!important;color:#fff!important;border:none!important;padding:10px!important;border-radius:8px!important;font-weight:700!important;font-size:13px!important;cursor:pointer!important;">${btnLabel}</button>`:'';
  return `<div style="padding:20px 20px 24px;border-bottom:1px solid ${LINE};">
    <div style="height:5px;border-radius:3px;margin-bottom:14px;background:${barBg};"></div>
    <div style="border-radius:12px;height:150px;display:flex;align-items:center;justify-content:center;margin-bottom:14px;background:${diagramBg};">${diagramSvg}</div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
      <span style="width:22px;height:22px;border-radius:50%;background:${numBg};color:#fff;font-size:12px;font-weight:800;display:inline-flex;align-items:center;justify-content:center;">${numLabel}</span>
      <span style="font-size:18px;font-weight:800;color:${INK};">${title}</span>
    </div>
    <span style="display:inline-block;font-size:10.5px;font-weight:700;letter-spacing:.06em;padding:4px 11px;border-radius:20px;margin-bottom:12px;text-transform:uppercase;background:${tagBg};color:${tagColor};">${tagText}</span>
    <div style="font-size:13.5px;line-height:1.4;color:${MUTE};margin-bottom:10px;">${desc}</div>
    <div style="font-size:11px;letter-spacing:.1em;margin:0 0 6px;color:#1e9e5a;">PROS</div>
    <ul style="list-style:none;margin-bottom:8px;">${prosHtml.replace(/<li>/g,'<li style="font-size:13.5px;line-height:1.4;padding:3px 0 3px 20px;position:relative;color:'+MUTE+';"><span style="position:absolute;left:0;color:#1e9e5a;font-weight:700;">&#10003;</span>')}</ul>
    <div style="font-size:11px;letter-spacing:.1em;margin:0 0 6px;color:#d94141;">CONS</div>
    <ul style="list-style:none;">${consHtml.replace(/<li>/g,'<li style="font-size:13.5px;line-height:1.4;padding:3px 0 3px 20px;position:relative;color:'+MUTE+';"><span style="position:absolute;left:0;color:#d94141;font-weight:700;">&#10007;</span>')}</ul>
    ${addBtn}
  </div>`;
}

