function bWires(){const sec=getSec('wires');const tvs=totalTVs();const visibleOpts=sec.options.filter(o=>{if(o.needsDrywall&&!canHideBehindWall())return false;if(o.hideForFrame&&isFrameTV)return false;return true;});if(isFrameTV&&hasDrywall()){visibleOpts.push({id:serviceConfig.oneConnectOptionId,label:'Install Samsung Frame OneConnect box behind the TV',price:350,_altSection:serviceConfig.oneConnectSectionId});}const wireTotal=(selections[sec.id]||[]).reduce((s,x)=>s+x.quantity,0);const wireBanner=tvs>0?(wireTotal<tvs?`<div style="${S.info}">📺 You have <strong>${tvs} TV${tvs>1?'s':''}</strong> — select a wire option for each (${wireTotal} of ${tvs} done).</div>`:`<div style="${S.ok}">✓ All ${tvs} TV${tvs>1?'s':''} have a wire option.</div>`):'';const opts=visibleOpts.map(o=>{const sid=o._altSection||sec.id;const q=getQty(sid,o.id);return `<div style="${S.qRow(q>0)}"><span style="flex:1!important;">${o.label}${S.price(o.price)}</span><div style="display:flex!important;align-items:center!important;gap:8px!important;flex-shrink:0!important;"><button class="dom-dec" data-s="${sid}" data-o="${o.id}" style="${S.qBtn}">−</button><span style="${S.qNum}">${q}</span><button class="dom-inc" data-s="${sid}" data-o="${o.id}" style="${S.qBtn}">+</button></div></div>`;}).join('');const wireOk=tvs===0||wireTotal===tvs;const findWire=name=>{const o=visibleOpts.find(o=>o.label===name);return o?o.id:'';};const wireHelpLink=`<button id="dom-wire-help" data-sec="${sec.id}" data-behind="${findWire('Yes, hide the wires BEHIND the wall')}" data-outside="${findWire('Yes, hide the wires OUTSIDE the wall')}" data-plug="${findWire('My wall already has a plug behind the TV')}" data-hang="${findWire('I want my wires to hang under the TV')}" style="${S.helpLink}">Not sure which to pick? See examples</button>`;return `<h1 style="${S.h1}">${sec.title}</h1><p style="${S.sub}">Select one per TV.</p>${wireHelpLink}${wireBanner}${opts}<div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${wireOk?S.btnPri:S.btnDis}" ${!wireOk?'disabled':''}>Continue →</button></div>`;}
function bLifting(){const sec=getSec('lifting');const isLarge=getMaxSizeCat()==='large';const visOpts=sec.options.filter(o=>o.forCat==='medium');const cur=(selections[sec.id]||[])[0]?.option_id;const LIFT={'1764782113636x102636028242952200':'Yes — I can help lift','1764782128214x566028847520153600':'No — Please bring a second technician','1764782163472x384097097839018000':'My TV is 85 inches or larger'};const subtitle=isLarge?'One or more of your TVs is 85" or larger. An additional technician is recommended to safely lift heavy TVs.':'One or more of your TVs is in the 70–85" range. Can you assist the technician lifting it onto the bracket?';const opts=visOpts.map(o=>{const on=cur===o.id;return `<div class="dom-sel" data-s="${sec.id}" data-o="${o.id}" style="${S.card(on)}"><span>${LIFT[o.id]||o.label}</span><span style="color:${on?BLUE:'#A7B3BE'}!important;font-size:18px!important;">${on?'●':'○'}</span></div>`;}).join('');const ok=!!cur;return `<h1 style="${S.h1}">Can you help us lift the TV?</h1><p style="${S.sub}">${subtitle}</p>${opts}<div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${ok?S.btnPri:S.btnDis}" ${!ok?'disabled':''}>Continue →</button></div>`;}
