function wire(root){root.querySelector('#btn-prev')?.addEventListener('click',()=>goBack());root.querySelector('#btn-next')?.addEventListener('click',()=>goNext());root.querySelector('#btn-submit')?.addEventListener('click',()=>doSubmit(root));root.querySelector('#btn-verify-zip')?.addEventListener('click',()=>doZip(root));{const bh=root.querySelector('#dom-bracket-help');if(bh)bh.addEventListener('click',()=>showBracketHelp(bh.dataset.sec,bh.dataset.flat,bh.dataset.tilt,bh.dataset.full));}{const sh=root.querySelector('#dom-surface-help');if(sh)sh.addEventListener('click',()=>showSurfaceHelp(sh.dataset.sec,{drywall:sh.dataset.drywall,brickstone:sh.dataset.brickstone,stone:sh.dataset.stone,stucco:sh.dataset.stucco}));}{const wh=root.querySelector('#dom-wire-help');if(wh)wh.addEventListener('click',()=>showWireHelp(wh.dataset.sec,{behind:wh.dataset.behind,outside:wh.dataset.outside,plug:wh.dataset.plug,hang:wh.dataset.hang}));}const applyCoupon=()=>{const raw=(root.querySelector('#c-coupon')?.value||'').trim();couponCode=raw;couponApplied=!!raw;if(raw)logEvent('answer','coupon:'+raw.toUpperCase());render();};root.querySelector('#btn-coupon-apply')?.addEventListener('click',applyCoupon);root.querySelector('#btn-coupon-toggle')?.addEventListener('click',()=>{couponBoxOpen=true;render();});root.querySelector('#c-sms-consent')?.addEventListener('change',e=>{smsConsent=e.target.checked;});root.querySelector('#cal-prev')?.addEventListener('click',()=>{calMonth--;if(calMonth<0){calMonth=11;calYear--;}render();});root.querySelector('#cal-next')?.addEventListener('click',()=>{calMonth++;if(calMonth>11){calMonth=0;calYear++;}render();});root.querySelector('#btn-dis-yes')?.addEventListener('click',()=>{const s=getSec('dismount');if(s)selectOnly(s.id,s.options[0].id);render();});root.querySelector('#btn-dis-no')?.addEventListener('click',()=>{const s=getSec('dismount');if(s)selectOnly(s.id,s.options[1].id);render();});const ta=root.querySelector('#dom-describe');if(ta)ta.addEventListener('input',e=>{describeText=e.target.value;const nb=root.querySelector('#btn-next'),on=describeText.trim().length>0;if(nb){nb.disabled=!on;nb.style.cssText=on?S.btnPri:S.btnDis;}e.target.style.borderColor=on?BLUE:LINE;});const vz=root.querySelector('#verify-zip');if(vz){vz.addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'').slice(0,5);e.target.value=digits;customer.zip=digits;const isValid=/^\d{5}$/.test(digits);const btn=root.querySelector('#btn-verify-zip');if(btn){btn.disabled=!isValid;btn.style.cursor=isValid?'pointer':'not-allowed';btn.style.opacity='1';}const msg=root.querySelector('#zip-msg');if(msg)msg.innerHTML='';if(isValid)doZip(root);});vz.addEventListener('keydown',e=>{if(e.key==='Enter')doZip(root);});}root.querySelectorAll('.dom-tv-type').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();const type=c.dataset.type;if(!selections['__frame_type'])selections['__frame_type']=[];const idx=selections['__frame_type'].indexOf(type);if(idx!==-1)selections['__frame_type'].splice(idx,1);else selections['__frame_type'].push(type);isFrameTV=selections['__frame_type'].includes('frame');const onlyFrame=isFrameTV&&!selections['__frame_type'].includes('regular');setQty(serviceConfig.frameBracketSectionId,serviceConfig.frameBracketOptionId,onlyFrame?(totalTVs()||1):0);render();}));root.querySelectorAll('.dom-inc').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const s=b.dataset.s,o=b.dataset.o;setQty(s,o,getQty(s,o)+1);render();}));root.querySelectorAll('.dom-dec').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const s=b.dataset.s,o=b.dataset.o;const q=getQty(s,o);if(q>0)setQty(s,o,q-1);render();}));root.querySelectorAll('.dom-sel').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();const s=c.dataset.s,o=c.dataset.o;selectOnly(s,o);render();}));root.querySelectorAll('.dom-date').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();selectedDate=c.dataset.date;selectedSlot=null;render();}));root.querySelectorAll('.dom-slot').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();selectedSlot=c.dataset.id;selectedSlotLabel=c.dataset.label||'';render();}));root.querySelectorAll('.dom-pdate').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();selectedDate=c.dataset.date;render();}));root.querySelectorAll('.dom-pslot').forEach(c=>c.addEventListener('click',e=>{e.stopPropagation();const id=c.dataset.id,date=c.dataset.date,label=c.dataset.label;const i=selectedSlots.findIndex(s=>s.id===id);if(i!==-1)selectedSlots.splice(i,1);else selectedSlots.push({id,date,label});render();}));root.querySelectorAll('.dom-comment').forEach(ta=>ta.addEventListener('input',e=>{optionComments[e.target.dataset.o]=e.target.value;}));root.querySelectorAll('input').forEach(inp=>{if(inp.id==='c-fn')inp.addEventListener('input',e=>{customer.first_name=e.target.value;});else if(inp.id==='c-ln')inp.addEventListener('input',e=>{customer.last_name=e.target.value;});else if(inp.id==='c-em')inp.addEventListener('input',e=>{customer.email=e.target.value;});else if(inp.id==='c-ph')inp.addEventListener('input',e=>{customer.phone=e.target.value;});else if(inp.id==='c-ad')inp.addEventListener('input',e=>{customer.address=e.target.value;});else if(inp.id==='c-zip')inp.addEventListener('input',e=>{customer.zip=e.target.value.replace(/\D/g,'');});else if(inp.id==='c-coupon'){inp.addEventListener('input',e=>{couponCode=e.target.value;couponApplied=false;});inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();applyCoupon();}});inp.addEventListener('blur',()=>{if((inp.value||'').trim())setTimeout(()=>applyCoupon(),0);});}});}
function goNext(){const steps=flowSteps();logStepAnswers(steps[stepIdx]);do{stepIdx++;}while(stepIdx<steps.length&&shouldSkip(steps[stepIdx]));if(stepIdx>=steps.length)return;if(steps[stepIdx]==='slots')fetchSlots();if(steps[stepIdx]==='prefslots')fetchSlots(120);render();}
function goBack(){const steps=flowSteps();do{stepIdx--;}while(stepIdx>=0&&shouldSkip(steps[stepIdx]));if(stepIdx<0)stepIdx=0;render();}
function orderedPreferred(){const out=[];for(const date of Object.keys(slotsByDate).sort()){for(const sl of(slotsByDate[date]||[])){if(selectedSlots.some(s=>s.id===sl.id)){const df=fmtDate(date);out.push({id:sl.id,date,label:sl.label,human:`${df.long}, ${df.date} — ${sl.label}`});}}}return out;}
function bPrefSlots(){const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];const DAYS=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const allDates=Object.keys(slotsByDate).sort();if(!allDates.length){return `<h1 style="${S.h1}">Pick a few times that work for you</h1><p style="color:${MUTE}!important;font-size:15px!important;margin-bottom:16px!important;">Loading available times…</p><div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button></div>`;}if(calYear===null){const f=new Date(allDates[0]+'T12:00:00');calYear=f.getFullYear();calMonth=f.getMonth();}const availSet=new Set(allDates);const firstDay=new Date(calYear,calMonth,1).getDay();const daysInMonth=new Date(calYear,calMonth+1,0).getDate();const todayStr=new Date().toISOString().slice(0,10);const firstAvail=new Date(allDates[0]+'T12:00:00');const lastAvail=new Date(allDates[allDates.length-1]+'T12:00:00');const canPrev=calYear>firstAvail.getFullYear()||(calYear===firstAvail.getFullYear()&&calMonth>firstAvail.getMonth());const canNext=calYear<lastAvail.getFullYear()||(calYear===lastAvail.getFullYear()&&calMonth<lastAvail.getMonth());const dayHdr=DAYS.map(d=>`<div style="text-align:center!important;font-size:12px!important;font-weight:600!important;color:${MUTE}!important;padding:4px 0 8px 0!important;">${d}</div>`).join('');let cells='';for(let i=0;i<firstDay;i++)cells+='<div></div>';for(let d=1;d<=daysInMonth;d++){const ds=`${calYear}-${String(calMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const has=availSet.has(ds),isSel=selectedDate===ds,isToday=ds===todayStr;const dayHasPicks=selectedSlots.some(s=>s.date===ds);if(has){cells+=`<div class="dom-pdate" data-date="${ds}" style="text-align:center!important;cursor:pointer!important;padding:4px 2px!important;border-radius:8px!important;background:${isSel?TINT:'transparent'}!important;"><div style="width:34px!important;height:34px!important;border-radius:50%!important;margin:0 auto!important;display:flex!important;align-items:center!important;justify-content:center!important;background:${isSel?BLUE:isToday?TINT:'transparent'}!important;font-size:15px!important;font-weight:${isSel||isToday?700:400}!important;color:${isSel?'#fff':isToday?BLUE:INK}!important;border:${dayHasPicks&&!isSel?'2px solid '+BLUE:(isToday&&!isSel?'1.5px solid '+BLUE:'none')}!important;">${d}</div></div>`;}else{cells+=`<div style="text-align:center!important;padding:4px 2px!important;"><div style="width:34px!important;height:34px!important;margin:0 auto!important;display:flex!important;align-items:center!important;justify-content:center!important;font-size:15px!important;color:#C2CCD6!important;">${d}</div></div>`;}}let timeHtml='';if(selectedDate&&slotsByDate[selectedDate]){const df=fmtDate(selectedDate);const slots=slotsByDate[selectedDate];if(!slots.length){timeHtml=`<div style="border-top:1px solid ${LINE}!important;margin-top:12px!important;padding-top:14px!important;"><p style="font-size:14px!important;color:${MUTE}!important;margin:0!important;text-align:center!important;">No times on ${df.date}. Please pick another day.</p></div>`;}else{const slotBtns=slots.map(sl=>{const on=selectedSlots.some(s=>s.id===sl.id);return `<div class="dom-pslot" data-id="${sl.id}" data-date="${selectedDate}" data-label="${sl.label}" style="background:${on?BLUE:'#fff'}!important;border:1.5px solid ${on?BLUE:LINE}!important;border-radius:8px!important;padding:13px 8px!important;cursor:pointer!important;text-align:center!important;"><span style="font-size:14px!important;font-weight:600!important;color:${on?'#fff':INK}!important;">${on?'&#10003; ':''}${sl.label}</span></div>`;}).join('');timeHtml=`<div style="border-top:1px solid ${LINE}!important;margin-top:12px!important;padding-top:12px!important;"><p style="font-size:14px!important;color:${MUTE}!important;margin:0 0 10px 0!important;font-weight:600!important;">${df.long}, ${df.date} — tap all times that work:</p><div style="display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important;">${slotBtns}</div></div>`;}}const picks=orderedPreferred();const pickSummary=picks.length?`<div style="background:${TINT}!important;border:1px solid ${BLUE_LIGHT}!important;border-radius:10px!important;padding:12px 14px!important;margin-bottom:14px!important;"><div style="font-size:13px!important;font-weight:700!important;color:${BLUE_DK}!important;margin-bottom:6px!important;">Your selected times (${picks.length})</div>${picks.map(p=>`<div style="font-size:13px!important;color:${INK}!important;margin-bottom:3px!important;">&#10003; ${p.human}</div>`).join('')}</div>`:'';const enough=picks.length>=2;const hint=enough?'':`<p style="font-size:13px!important;color:${MUTE}!important;text-align:center!important;margin:0 0 10px 0!important;">Please select at least <strong>2 times</strong> so we can confirm the best one.</p>`;return `<h1 style="${S.h1}">Pick a few times that work for you</h1><p style="${S.sub}">Choose at least 2 time slots that fit your schedule. We'll confirm the best one and follow up with your quote.</p>${pickSummary}<div style="background:#fff!important;border:1px solid ${LINE}!important;border-radius:10px!important;padding:14px!important;margin-bottom:14px!important;"><div style="display:flex!important;align-items:center!important;justify-content:space-between!important;margin-bottom:10px!important;"><button id="cal-prev" style="background:transparent!important;border:1px solid ${LINE}!important;color:${canPrev?BLUE:'#C2CCD6'}!important;width:32px!important;height:32px!important;border-radius:50%!important;cursor:${canPrev?'pointer':'default'}!important;font-size:18px!important;display:flex!important;align-items:center!important;justify-content:center!important;" ${!canPrev?'disabled':''}>&#8249;</button><span style="font-size:16px!important;font-weight:700!important;color:${INK}!important;">${MONTHS[calMonth]} ${calYear}</span><button id="cal-next" style="background:transparent!important;border:1px solid ${LINE}!important;color:${canNext?BLUE:'#C2CCD6'}!important;width:32px!important;height:32px!important;border-radius:50%!important;cursor:${canNext?'pointer':'default'}!important;font-size:18px!important;display:flex!important;align-items:center!important;justify-content:center!important;" ${!canNext?'disabled':''}>&#8250;</button></div><div style="display:grid!important;grid-template-columns:repeat(7,1fr)!important;">${dayHdr}</div><div style="display:grid!important;grid-template-columns:repeat(7,1fr)!important;">${cells}</div>${timeHtml}</div>${hint}<div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${enough?S.btnPri:S.btnDis}" ${!enough?'disabled':''}>Continue →</button></div>`;}
